function utf8Bytes(str){
  var out=[];
  for(var i=0;i<str.length;i++){
    var c=str.charCodeAt(i);
    if(c<0x80) out.push(c);
    else if(c<0x800){ out.push(0xC0|(c>>6), 0x80|(c&0x3F)); }
    else if(c>=0xD800&&c<=0xDBFF){ var c2=str.charCodeAt(++i); var cp=0x10000+((c&0x3FF)<<10)+(c2&0x3FF); out.push(0xF0|(cp>>18),0x80|((cp>>12)&0x3F),0x80|((cp>>6)&0x3F),0x80|(cp&0x3F)); }
    else { out.push(0xE0|(c>>12), 0x80|((c>>6)&0x3F), 0x80|(c&0x3F)); }
  }
  return out;
}
function hexToBytes(hex){
  hex=String(hex).replace(/0x/i,'').replace(/[^0-9a-fA-F]/g,'');
  var out=[]; for(var i=0;i+1<hex.length;i+=2){ out.push(parseInt(hex.substr(i,2),16)); }
  if(hex.length%2===1) out.push(parseInt(hex.substr(hex.length-1),16));
  return out;
}
function pad8(n){ var s=n.toString(16); while(s.length<8)s='0'+s; return s; }
function hexdump(bytes, opts){
  opts=opts||{};
  var width=opts.width||16;
  var lines=[];
  for(var off=0; off<bytes.length; off+=width){
    var chunk=bytes.slice(off, off+width);
    var hex=chunk.map(function(b){ return (b&0xff).toString(16).padStart(2,'0'); }).join(' ');
    while(hex.length<width*3-1) hex+=' ';
    var ascii=chunk.map(function(b){ return (b>=32&&b<127)?String.fromCharCode(b):'.'; }).join('');
    lines.push(pad8(off)+'  '+hex+'  |'+ascii+'|');
  }
  return lines.join('\n');
}
function inputToBytes(text, mode){
  return mode==='hex' ? hexToBytes(text) : utf8Bytes(text);
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { utf8Bytes:utf8Bytes, hexToBytes:hexToBytes, hexdump:hexdump, inputToBytes:inputToBytes, pad8:pad8 };
}
